"""Small offline gallery for five exploratory reference-led paintings."""
from pathlib import Path
from PIL import Image
import json
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'art/concepts/reference-creatures-v1';SOURCE=ROOT/'art/source/reference-creatures-v1'
manifest=json.loads((SOURCE/'generation.json').read_text())
notes={
'veiled-sovereign':('Empty veil, pale articulated armour and a thin thorn halo.','Review the crown/armour relationship and the broad black mantle. Fine cloth webs would need simplification at game scale.'),
'thorn-regent':('Raised palms, a sinewy crowned torso, fibrous train and heavy segmented tail.','The tail and train are deliberately distinct. Hand detail and crown spines are concept-level marks, not registered rig parts.'),
'cinder-eye':('One red eye-ring in a heavy horned mass, with four separated arms.','The singular eye is the focus. Horn and plate density would need a selected simplification pass before any small sprite.'),
'pale-hollow':('A blank head, throat opening, hollow torso and four long uneven arms.','The torso gap and arm spacing carry the design. No animation, walking support or attack behaviour is implied.'),
'ribbound-wraith':('A small hanging skull inside an oversized rib canopy, with hooked limbs and sparse connective strands.','The dorsal peak reaches the upper canvas edge; a production framing pass would add margin and simplify fine rib/web detail.')}
order=list(notes);byid={e['id']:e for e in manifest['assets']};refs={r['id']:r for r in manifest['references']};entries=[]
for ident in order:
 e=byid[ident];entries.append({**e,'file':ident+'.png','reference':refs[ident]['copy'],'idea':notes[ident][0],'review_focus':notes[ident][1],'owner_selection':None,'size':list(Image.open(OUT/(ident+'.png')).size)})
cat={'issue':153,'status':'Exploratory concepts; selection and production scope open','entries':entries,'references':manifest['references']}
(OUT/'catalog.json').write_text(json.dumps(cat,indent=2)+'\n',encoding='utf-8',newline='\n')
html=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Depths · Five creature studies</title><style>
@font-face{font-family:Field;src:url('../../fonts/source-sans-3/SourceSans3-Variable.ttf')}*{box-sizing:border-box}:root{font:17px/1.5 Field,system-ui,sans-serif;color:#e0d8c6;background:#161915;color-scheme:dark}body{max-width:1400px;margin:auto;padding:24px clamp(14px,3vw,32px) 60px}h1,h2,h3{font-weight:500;line-height:1.15}h1{font-size:clamp(30px,4vw,43px)}h2{font-size:29px}p{color:#b9bead;max-width:90ch}a,summary{color:#dbc187}button,select{font:inherit;background:#283127;color:inherit;border:1px solid #687056;border-radius:3px;min-height:44px;padding:8px 12px;max-width:100%;cursor:pointer}.controls{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin:20px 0}label{min-height:44px;display:flex;gap:8px;align-items:center;flex-wrap:wrap}input{width:22px;height:22px}.viewer{display:grid;grid-template-columns:1fr;gap:20px;align-items:start}.viewer.compare{grid-template-columns:1fr 1fr}figure{margin:0;min-width:0}figure img{display:block;width:100%;max-height:950px;object-fit:contain;background:#0c110e}figcaption{color:#b8beaa;padding-top:8px;font-size:15px}.grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}.card{min-width:0;padding:10px;background:#242c22;border:1px solid #45523e}.card img{display:block;width:100%;height:auto;aspect-ratio:2/3;object-fit:contain}.card h3{font-size:20px;margin:12px 0}.card button{padding:0;border:0;display:block;width:100%;text-align:left;background:transparent}.note{border-left:2px solid #817b52;padding-left:14px}summary{cursor:pointer;min-height:44px;padding:10px 0}details{border-top:1px solid #46513e;margin-top:14px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.5 Field,system-ui}button:focus-visible,select:focus-visible,summary:focus-visible,a:focus-visible{outline:3px solid #d9bc7e;outline-offset:3px}[hidden]{display:none!important}@media(max-width:800px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.viewer.compare{grid-template-columns:1fr}}@media(max-width:450px){.controls{gap:7px}.card h3{font-size:18px}}
</style></head><body><header><p>DEPTHS · EXPLORATORY ART · 153</p><h1>Five creature studies</h1><p>Reference-led reimaginings of five distinct silhouettes: veiled authority, sinewy ritual posture, a single red focus, pale impossible anatomy and a suspended rib cage. Working labels only; story roles and production choices remain open.</p><p><a href="../../../docs/reference-creature-concepts.md">Handoff and prompt set</a> · <a href="#comparison">Compare all five</a></p></header>
<div class="controls"><label>Study <select id="study"></select></label><button id="prev">Previous</button><button id="next">Next</button><label><input id="compare" type="checkbox">Show supplied reference</label><a id="original" target="_blank" rel="noopener">Full original painting</a></div><h2 id="title"></h2><p id="idea"></p><div id="viewer" class="viewer"><figure><img id="art" alt="Selected creature concept"><figcaption>Built-in ImageGen concept painting</figcaption></figure><figure id="reference-panel" hidden><img id="reference" alt="User-supplied visual reference"><figcaption>Supplied reference · creator/attribution details were not provided.</figcaption></figure></div><p id="focus" class="note"></p><p>Concept paintings only. No runtime exports, animation, enemy rules, encounters or lore have been assigned.</p><h2 id="comparison">The five directions</h2><div id="gallery" class="grid"></div><details><summary>Exact prompts, references and preserved originals</summary><div id="sources"></div></details><script>
const DATA=__DATA__,by=id=>document.getElementById(id),cache=new Map();let ticket=0;window.reviewState={id:DATA.entries[0].id};
function image(src){if(!cache.has(src)){const i=new Image();i.src=src;cache.set(src,i.decode().then(()=>i))}return cache.get(src)}
async function paint(){const mine=++ticket,e=DATA.entries.find(e=>e.id===reviewState.id),ref='../../../'+e.reference;await Promise.all([image(e.file),image(ref)]);if(mine!==ticket)return;by('study').value=e.id;by('title').textContent=e.title;by('idea').textContent=e.idea;by('focus').textContent=e.review_focus;by('art').src=e.file;by('art').alt=e.title+' concept';by('reference').src=ref;by('reference').alt=e.title+' supplied reference';by('original').href=e.file;return Promise.all([by('art').decode(),by('reference').decode()]).catch(error=>{if(mine===ticket)throw error})}
function choose(id){reviewState.id=id;window.viewReady=paint();return window.viewReady}
for(const e of DATA.entries){by('study').append(new Option(e.title,e.id));const c=document.createElement('article'),b=document.createElement('button'),i=new Image(),h=document.createElement('h3');c.className='card';c.dataset.id=e.id;i.src=e.file;i.alt=e.title;h.textContent=e.title;b.append(i,h);b.onclick=()=>{choose(e.id);by('title').scrollIntoView({behavior:'smooth',block:'start'})};c.append(b);by('gallery').append(c);const d=document.createElement('details'),s=document.createElement('summary'),a=document.createElement('a'),p=document.createElement('pre');s.textContent=e.title;a.href='../../../'+e.source;a.textContent='Original master · '+e.sha256.slice(0,12);p.textContent=e.prompt;d.append(s,a,p);by('sources').append(d)}
by('study').onchange=()=>choose(by('study').value);for(const [id,step]of [['prev',-1],['next',1]])by(id).onclick=()=>{const a=DATA.entries;choose(a[(a.findIndex(e=>e.id===reviewState.id)+step+a.length)%a.length].id)};by('compare').onchange=()=>{by('reference-panel').hidden=!by('compare').checked;by('viewer').classList.toggle('compare',by('compare').checked)};window.artReadyPromise=Promise.all([choose(reviewState.id),...DATA.entries.map(e=>image(e.file))]);
</script></body></html>'''
(OUT/'inspector.html').write_text(html.replace('__DATA__',json.dumps(cat)),encoding='utf-8',newline='\n')
print('REFERENCE_CREATURE_REVIEW:',len(entries),'concept paintings')
